// @vitest-environment node
// Generated by /ship Step 7 coverage audit.
import { randomUUID } from 'node:crypto'

import { eq } from 'drizzle-orm'
import { afterEach, expect, test, vi } from 'vitest'

import { db } from '@/db'
import { syncReceiptTable, userTable } from '@/db/schema'
import { runTransaction } from '@/db/transaction'

import { describeIfDb } from './describeIfDb'
import {
  digestOperation,
  findStoredReceipt,
  readStoredReceipts,
} from './syncReceiptStore'

vi.setConfig({ testTimeout: 30000 })
const owners: number[] = []

/** Inserts a synthetic user and returns its id. */
async function createUser() {
  const [user] = await db
    .insert(userTable)
    .values({ clerkId: `test_receipt_${randomUUID()}` })
    .returning()
  owners.push(user!.id)
  return user!.id
}

afterEach(async () => {
  for (const id of owners.splice(0)) {
    await db.delete(syncReceiptTable).where(eq(syncReceiptTable.userId, id))
    await db.delete(userTable).where(eq(userTable.id, id))
  }
})

// Value: protects=retry detection by digest; fails_when=identical wire bytes digest differently or different bytes collide; why_new=no direct test; seam=none; no_claim=db
test('identical wire operations share a digest and a changed field does not', () => {
  // Arrange
  const a = { operationId: 'x', type: 'rename', name: 'A' }

  // Act
  const same = digestOperation({ ...a })
  const changed = digestOperation({ ...a, name: 'B' })

  // Assert
  expect(same).toBe(digestOperation(a))
  expect(same).toMatch(/^[0-9a-f]{64}$/)
  expect(changed).not.toBe(same)
})

// Value: protects=cross-account receipt isolation; fails_when=another user's receipt is returned; why_new=no direct test; seam=none; no_claim=procedure wiring
describeIfDb('stored sync receipts', () => {
  test('return only the owner receipts and never those of another account', async () => {
    // Arrange
    const owner = await createUser()
    const stranger = await createUser()
    const operationId = randomUUID()
    const outcome = {
      kind: 'category',
      operationId,
      result: 'applied',
      serverId: 7,
    } as const
    await db.insert(syncReceiptTable).values({
      userId: owner,
      operationId,
      payloadDigest: digestOperation({ operationId }),
      outcome,
    })

    // Act
    const ownerFound = await runTransaction(async (tx) =>
      findStoredReceipt(tx, owner, operationId),
    )
    const strangerFound = await runTransaction(async (tx) =>
      findStoredReceipt(tx, stranger, operationId),
    )
    const ownerRead = await readStoredReceipts(owner, [operationId], (o) => o)
    const strangerRead = await readStoredReceipts(
      stranger,
      [operationId],
      (o) => o,
    )

    // Assert
    expect(ownerFound?.payloadDigest).toBe(digestOperation({ operationId }))
    expect(strangerFound).toBeUndefined()
    expect(ownerRead).toEqual([outcome])
    expect(strangerRead).toEqual([])
  })
})
